    if (putchar('[') == EOF) return 74;
    for (int32_t i = 0; i < BERYL_OUTPUT_COUNT; ++i) {
        if (i && putchar(',') == EOF) return 74;
        if (printf("%" PRId32, output[i]) < 0) return 74;
    }
    if (puts("]") == EOF || fflush(stdout) == EOF) return 74;
    return 0;
}

